// Built-in, hand-written command reference for the analyst ("What this command does").
// Deliberately NOT generated by the LLM: fixed text, instant, and never hallucinates.
// Explains what a command does; it does not score it (scoring stays in the backend).

export interface Mitre { id: string; name: string; }
export interface Explanation {
    label: string;   // short title
    what: string;    // what the command does
    why: string;     // why an attacker would run it
    mitre?: Mitre;   // MITRE ATT&CK technique, only where the mapping is clear-cut
}

const T = (id: string, name: string): Mitre => ({ id, name });

// 1) Specific patterns, checked against the whole command line (first match wins)
const PATTERNS: { re: RegExp; ex: Explanation }[] = [
    {
        re: /(\bnc\b|\bncat\b).*\s-e\s|\/dev\/tcp\/|\bbash\s+-i\b|\bsh\s+-i\b/,
        ex: {
            label: 'Reverse shell attempt',
            what: "Tries to open a shell that connects back to the attacker's own machine.",
            why: 'Gives the attacker an interactive foothold that does not depend on this SSH login.',
            mitre: T('T1059.004', 'Command and Scripting Interpreter: Unix Shell'),
        },
    },
    {
        re: /\b(curl|wget)\b[^|]*\|\s*(sudo\s+)?(ba|z|da)?sh\b/,
        ex: {
            label: 'Download and run a script',
            what: 'Downloads a script and pipes it straight into the shell to execute it.',
            why: 'A common one-step way to install malware, miners or botnet clients.',
            mitre: T('T1059.004', 'Command and Scripting Interpreter: Unix Shell'),
        },
    },
    {
        re: /(>>?|\btee\b|\bcp\b|\bmv\b).*authorized_keys/,
        ex: {
            label: 'Plant an SSH key',
            what: "Writes a key into the account's SSH authorized_keys file.",
            why: 'Their own key lets the attacker log back in later without a password.',
            mitre: T('T1098.004', 'Account Manipulation: SSH Authorized Keys'),
        },
    },
    {
        re: /authorized_keys/,
        ex: {
            label: 'Inspect SSH access',
            what: 'Reads the list of keys allowed to log into this account.',
            why: 'Shows who can log in, and where a backdoor key could be added.',
        },
    },
    {
        re: /(>>|\btee\b).*\/etc\/passwd/,
        ex: {
            label: 'Add an account via /etc/passwd',
            what: 'Appends a line to /etc/passwd, which defines user accounts.',
            why: 'A crafted line can create a hidden root-level account.',
            mitre: T('T1136.001', 'Create Account: Local Account'),
        },
    },
    {
        re: /\/etc\/shadow/,
        ex: {
            label: 'Read password hashes',
            what: 'Accesses /etc/shadow, which stores the hashed passwords of every user.',
            why: 'The hashes can be cracked offline to recover real passwords.',
            mitre: T('T1003.008', 'OS Credential Dumping: /etc/passwd and /etc/shadow'),
        },
    },
    {
        re: /\/etc\/passwd/,
        ex: {
            label: 'List user accounts',
            what: 'Reads /etc/passwd, the list of user accounts on the system.',
            why: 'Shows which accounts exist and which can log in, to choose targets.',
            mitre: T('T1087.001', 'Account Discovery: Local Account'),
        },
    },
    {
        re: /\bsudo\s+-l\b|\/etc\/sudoers/,
        ex: {
            label: 'Check sudo rights',
            what: 'Lists what the current user is allowed to run as root.',
            why: 'Looks for a path to administrator (root) privileges.',
            mitre: T('T1548.003', 'Abuse Elevation Control Mechanism: Sudo and Sudo Caching'),
        },
    },
    {
        re: /\b(rm|shred|truncate|unlink)\b.*\/var\/log|>\s*\/var\/log/,
        ex: {
            label: 'Wipe system logs',
            what: 'Deletes or empties files under /var/log, where the system records activity.',
            why: 'Erases evidence of the intrusion.',
            mitre: T('T1070.002', 'Indicator Removal: Clear Linux or Mac System Logs'),
        },
    },
    {
        re: /\bhistory\s+-c\b|unset\s+histfile|histfile=|\b(rm|shred)\b.*\.bash_history|>\s*\S*\.bash_history/,
        ex: {
            label: 'Clear shell history',
            what: 'Clears or disables the record of typed commands.',
            why: 'Hides what the attacker did from administrators.',
            mitre: T('T1070.003', 'Indicator Removal: Clear Command History'),
        },
    },
    {
        re: /\.bash_history/,
        ex: {
            label: 'Read command history',
            what: 'Reads the file of commands previously typed on this account.',
            why: 'Old commands often contain passwords, hostnames and file paths.',
            mitre: T('T1552.003', 'Unsecured Credentials: Bash History'),
        },
    },
    {
        re: /-perm\s+(-|\/)?[0-7]*4000|-perm\s+-u=s/,
        ex: {
            label: 'Find SUID programs',
            what: 'Searches for programs that always run with their owner\'s (often root\'s) privileges.',
            why: 'A misconfigured SUID program can be abused to become root.',
            mitre: T('T1548.001', 'Abuse Elevation Control Mechanism: Setuid and Setgid'),
        },
    },
    {
        re: /\.env\b|id_rsa|\.pem\b|\.aws\/credentials|wp-config|config\.php|\bgrep\b.*(pass|secret|token|api[_-]?key)/,
        ex: {
            label: 'Hunt for credentials',
            what: 'Looks for passwords, private keys or tokens stored in files.',
            why: 'Stored secrets can unlock databases, cloud accounts or other servers.',
            mitre: T('T1552.001', 'Unsecured Credentials: Credentials In Files'),
        },
    },
    {
        re: /\bcrontab\b|\/etc\/cron/,
        ex: {
            label: 'Scheduled tasks (cron)',
            what: "Views or edits cron, the system's list of scheduled tasks.",
            why: 'Attackers add cron jobs so their code runs again automatically.',
            mitre: T('T1053.003', 'Scheduled Task/Job: Cron'),
        },
    },
    {
        re: /os-release|\/proc\/version|\/etc\/issue/,
        ex: {
            label: 'Fingerprint the system',
            what: 'Reads the operating system name and version.',
            why: 'Used to pick exploits that work on this exact system.',
            mitre: T('T1082', 'System Information Discovery'),
        },
    },
];

