const BY_NAME = new Map<string, Explanation>();
for (const { cmds, ex } of BY_COMMAND) for (const c of cmds) BY_NAME.set(c, ex);

export function explainCommand(command: string): Explanation | null {
    const c = command.trim().toLowerCase().replace(/\s+/g, ' ');
    if (!c) return null;

    for (const { re, ex } of PATTERNS) if (re.test(c)) return ex;

    // Base command of the first segment; "sudo X" explains X (unless X is unknown).
    const first = c.split(/\|\||&&|[|;]/)[0].trim();
    const tokens = first.split(' ');
    let base = tokens[0].split('/').pop() ?? '';
    if (base === 'sudo' && tokens.length > 1) {
        const inner = (tokens[1].startsWith('-') ? tokens[2] : tokens[1]) ?? '';
        const innerEx = BY_NAME.get(inner.split('/').pop() ?? '');
        if (innerEx) return { ...innerEx, label: `${innerEx.label} (as root via sudo)` };
        base = 'sudo';
    }
    const known = BY_NAME.get(base);
    if (known) return known;
    // Started by path (./x.sh, /tmp/payload): running a file rather than a known command
    if (tokens[0].includes('/')) return RUN_PROGRAM;
    return null;
}

const RUN_PROGRAM: Explanation = {
    label: 'Run a program',
    what: 'Executes a file directly from a folder on the server.',
    why: 'Usually a tool or script the attacker has just downloaded or created.',
};
